function accountControls(build,index){const box=el('div',undefined,'stats-account-settings');for(const [key,title,available] of [['useRoster','Use My Tatari settings',!!accountRoster],['useBadges','Use My Badges',!!accountLevels]]){const label=el('label'),check=el('input');check.type='checkbox';check.checked=!!build[key];check.disabled=accountLoading||!accountActor||!available;check.setAttribute('aria-label',title+' for Tatari '+(index+1));check.onchange=()=>{if(check.checked&&key==='useRoster'){let next={...build};if(!accountRoster.units[next.pet]?.owned){const owned=data.units.find(u=>accountRoster.units[u.id]?.owned);if(!owned){$('tool-status').textContent='Mark owned Tatari in My Tatari first.';check.checked=false;return}next.pet=owned.id}Object.assign(build,applyOwnedTatari(next,accountRoster));build.progress=0}if(check.checked&&key==='useBadges'){build.badges=accountBadgeIds(data,accountLevels);build.badgeMode=build.badges.length?'pick':'none'}build[key]=check.checked;render()};label.append(check,el('span',title));box.append(label)}if(accountLoading)box.append(el('small','Loading saved settings…'));else if(!accountActor){const link=el('a','Log in to use saved settings');link.href=accountUrl;box.append(link)}else if(accountError)box.append(el('small',accountError));return box}
async function loadAccount(){const token=++accountGeneration;accountLoading=true;accountActor=null;accountRoster=null;accountLevels=null;accountError='';for(const build of builds)if(build.useRoster||build.useBadges)Object.assign(build,{tier:1,stars:1,food:1,level:500,progress:0,badgeMode:'none',badges:[],useRoster:false,useBadges:false});if(data)render();try{const user=await currentUser();if(token!==accountGeneration)return;if(!user)return;const rows=await Promise.allSettled([loadRoster(user.id),loadSettings()]);if(token!==accountGeneration)return;const active=await currentUser();if(token!==accountGeneration||active?.id!==user.id)return;accountActor=user.id;if(rows[0].status==='fulfilled')accountRoster=rows[0].value?.roster||{accountLevel:1,units:{}};else accountError='Saved Tatari could not load. Refresh to retry.';if(rows[1].status==='fulfilled')accountLevels=rows[1].value;else accountError+=' Saved badges could not load. Refresh to retry.';}catch(e){if(token===accountGeneration)accountError='Saved settings could not load.'}finally{if(token===accountGeneration){accountLoading=false;if(data)render()}}}
